// 2. the min.insync.replicas that applies to this topic
var res = new ConfigResource(ConfigResource.Type.TOPIC, "payments");
int minIsr = Integer.parseInt(admin.describeConfigs(List.of(res)).all().get()
        .get(res).get("min.insync.replicas").value());

// 3. classify every partition
for (TopicPartitionInfo p : desc.partitions()) {
    int isr = p.isr().size(), replicas = p.replicas().size();
    if (isr < minIsr) {
        System.out.printf("partition %d: ISR %d < min %d, acks=all writes refused%n", p.partition(), isr, minIsr);
    } else if (isr < replicas) {
        System.out.printf("partition %d: under-replicated, %d of %d in sync%n", p.partition(), isr, replicas);
    }
}

